    pub fn parse_ws_liquidation(&self, liquidation: &crate::value::Dict, market: Option<&crate::types::Market>) -> crate::value::Dict {
        //
        //     {
        //         "id": "1718179273230201709233240002",
        //         "market": "XRP-USD-PERP",
        //         "side": "SELL",
        //         "size": "120",
        //         "price": "1.2854",
        //         "created_at": 1718179273230,
        //         "trade_type": "LIQUIDATION"
        //     }
        //
        let marketId: Option<String> = self.safe_string_k_opt(&liquidation, "market", &[]);
        let marketResolved: crate::types::Market = self.safe_market(marketId.as_deref(), market, &[]);
        let timestamp: Option<i64> = self.safe_integer_k(&liquidation, "created_at", &[]).as_i64();
        let contracts: Option<String> = self.safe_string_k_opt(&liquidation, "size", &[]);
        let price: Option<String> = self.safe_string_k_opt(&liquidation, "price", &[]);
        return self.safe_liquidation(std::sync::Arc::new({
    let mut m = indexmap::IndexMap::new();
        m.insert("info".to_string(), Value::Dict(liquidation.clone()));
        m.insert("symbol".to_string(), crate::value::KeyRead::key_read(&&marketResolved, "symbol"));
        m.insert("contracts".to_string(), self.parse_number(Value::from(contracts.as_deref()), &[]));
        m.insert("contractSize".to_string(), Value::Null);
        m.insert("price".to_string(), self.parse_number(Value::from(price.as_deref()), &[]));
        m.insert("side".to_string(), self.safe_string_lower_k(&liquidation, "side", &[]));
        m.insert("baseValue".to_string(), self.parse_number(Value::from(contracts.as_deref()), &[]));
        m.insert("quoteValue".to_string(), self.parse_number(crate::precise::Precise::stringMul(&contracts, &price), &[]));
        m.insert("timestamp".to_string(), Value::from(timestamp));
        m.insert("datetime".to_string(), self.iso8601(timestamp));
    m
}), &[crate::Value::from(&marketResolved)]);

    Default::default()
}

    pub fn handle_trade(&mut self, client: &crate::pro::ws_client::ClientHandle, message: &crate::value::Dict) -> crate::value::Dict {
        let __pro_message: &indexmap::IndexMap<String, Value> = &message;
        //
        //     {
        //         "jsonrpc": "2.0",
        //         "method": "subscription",
        //         "params": {
        //             "channel": "trades.ALL",
        //             "data": {
        //                 "id": "1718179273230201709233240002",
        //                 "market": "kBONK-USD-PERP",
        //                 "side": "BUY",
        //                 "size": "34028",
        //                 "price": "0.028776",
        //                 "created_at": 1718179273230,
        //                 "trade_type": "FILL"
        //             }
        //         }
        //     }
        //
        let params: crate::value::Dict = __pro_message.key_dict("params");
        let data: crate::value::Dict = self.safe_dict_k_t(&params, "data");
        let parsedTrade: crate::value::Dict = self.parse_trade(Value::from(&data), None);
        let symbol: Option<String> = self.safe_string_k_opt(&parsedTrade, "symbol", &[]);
        let messageHash: Option<String> = self.safe_string_k_opt(&params, "channel", &[]);
        let mut stored: Option<crate::pro::cache::Cache> = self.trades.lookup(&symbol);
        if (stored.is_none()) {
            stored = Some(ArrayCache::new(self.safe_integer_k(&self.options, "tradesLimit", &[Value::Int(1000)])));
            CacheStore::put(&mut self.trades, &symbol, stored.clone());
        }
        stored.append(Value::Dict(parsedTrade));
        client.resolve(Value::from(&stored), messageHash.as_deref());
        if (self.safe_string_k(&data, "trade_type", &[]).as_str() == Some("LIQUIDATION")) {
            // one cache per market, kept in the options next to the request id counter: this.liquidations
            // is typed as a single cache in some languages and initialized as a map in others
            let liquidation: crate::value::Dict = self.parse_ws_liquidation(&data, None);
            let mut caches: indexmap::IndexMap<String, Value> = self.safe_dict_k(&self.options, "liquidationsBySymbol", &[Value::Map({
                let m = indexmap::IndexMap::new();
                m
            })]).as_map().cloned().unwrap_or_default();
            let mut liquidations: Value = self.safe_value(&caches, Value::from(symbol.as_deref()), &[]);
            if (liquidations == Value::Null) {
                liquidations = Value::from(ArrayCache::new(self.safe_integer_k(&self.options, "liquidationsLimit", &[Value::Int(1000)])));
                caches.insert(symbol.as_deref().unwrap_or("null").to_string(), liquidations.clone());
                { let __d = &mut self.options; std::sync::Arc::make_mut(__d).insert("liquidationsBySymbol".into(), Value::Map(caches)); }
            }
            liquidations.append(Value::Dict(liquidation));
            if (symbol.is_some()) {
                client.resolve(liquidations, &(Value::Str(format!("{}{}", "liquidations:", symbol.as_deref().unwrap_or("null")).into())));
            }
        }
        // an SBE frame names its market but not the subscription it was sent for,
        // so the trades.ALL subscription is resolved from the per-market channel too
        let isSbe: bool = (match __pro_message.get("sbe").cloned() { Some(__v) if matches!(__v, Value::Bool(_)) => __v, _ => Value::Bool(false) }).as_bool().unwrap_or(false);
        if isSbe && (messageHash.as_deref() != Some("trades.ALL")) {
            client.resolve(Value::from(&stored), "trades.ALL");
        }
        return std::sync::Arc::clone(message);
}

