        m.insert("ask".to_string(), self.safe_string_k(&data, "ask", &[]));
        m.insert("askVolume".to_string(), self.safe_string_k(&data, "ask_size", &[]));
        m.insert("bid".to_string(), self.safe_string_k(&data, "bid", &[]));
